{
  "documentVersion": 1,
  "template": "gas",
  "recipe": {
    "schemaVersion": 1,
    "composition": {
      "ref": "compositions/GasPressureExperiment",
      "version": 1
    },
    "parameters": {}
  },
  "lesson": {
    "title": "Gas Pressure",
    "instruction": "Make the container smaller. What happens to the pressure?",
    "explanation": ""
  },
  "presentation": {
    "layout": "right",
    "view": "gas",
    "particles": true,
    "directShading": true,
    "camera": "overview",
    "controls": [
      {
        "id": "control-volume",
        "capability": "volume",
        "label": "Volume",
        "target": "session",
        "widget": "slider",
        "slot": "primary",
        "min": 0.25,
        "max": 2,
        "step": 0.05
      },
      {
        "id": "control-temperature",
        "capability": "temperature",
        "label": "Temperature",
        "target": "session",
        "widget": "slider",
        "slot": "details",
        "min": 100,
        "max": 600,
        "step": 10
      },
      {
        "id": "control-amount",
        "capability": "amount",
        "label": "Amount of gas",
        "target": "session",
        "widget": "slider",
        "slot": "details",
        "min": 0.1,
        "max": 5,
        "step": 0.1
      },
      {
        "id": "control-playing",
        "capability": "playing",
        "label": "Particle motion",
        "target": "session",
        "widget": "toggle",
        "slot": "details"
      },
      {
        "id": "control-reset",
        "capability": "reset",
        "label": "Reset",
        "target": "session",
        "widget": "button",
        "slot": "primary"
      }
    ],
    "results": [
      {
        "id": "result-pressureKPa",
        "output": "pressureKPa",
        "label": "Pressure",
        "target": "session",
        "unit": "kPa",
        "precision": 2,
        "slot": "primary"
      }
    ]
  },
  "editor": {
    "positions": {},
    "zoom": 0.7
  }
}

