  "recipe": {
    "schemaVersion": 1,
    "composition": {
      "ref": "assemblies/GeneratedExperiment",
      "version": 1
    },
    "parameters": {},
    "assembly": {
      "version": 1,
      "title": "Line slope",
      "learningGoal": "Change the slope and intercept. What happens to the line?",
      "instances": [
        {
          "id": "line/main",
          "label": "Line",
          "prefab": {
            "ref": "prefabs/math-foundations/Line",
            "version": 1
          },
          "parameters": {
            "slope": 1,
            "intercept": 0,
            "xMin": -5,
            "xMax": 5
          }
        }
      ],
      "observations": [
        {
          "id": "observe-equation",
          "instance": "line/main",
          "output": "equation",
          "unit": "1"
        },
        {
          "id": "observe-yAtZero",
          "instance": "line/main",
          "output": "yAtZero",
          "unit": "math units"
        },
        {
          "id": "observe-yAtOne",
          "instance": "line/main",
          "output": "yAtOne",
          "unit": "math units"
        },
        {
          "id": "observe-rise",
          "instance": "line/main",
          "output": "rise",
          "unit": "1"
        },
        {
          "id": "observe-run",
          "instance": "line/main",
          "output": "run",
          "unit": "1"
        }
      ],
      "connections": [
        {
          "type": "observation-source",
          "from": {
            "instance": "line/main",
            "output": "equation"
          },
          "to": "observe-equation"
        },
        {
          "type": "observation-source",
          "from": {
            "instance": "line/main",
            "output": "yAtZero"
          },
          "to": "observe-yAtZero"
        },
        {
          "type": "observation-source",
          "from": {
            "instance": "line/main",
            "output": "yAtOne"
          },
          "to": "observe-yAtOne"
        },
        {
          "type": "observation-source",
          "from": {
            "instance": "line/main",
            "output": "rise"
          },
          "to": "observe-rise"
        },
        {
          "type": "observation-source",
          "from": {
            "instance": "line/main",
            "output": "run"
          },
          "to": "observe-run"
        }
      ],
      "controls": [
        {
          "instance": "line/main",
          "action": "SET_SLOPE"
        },
        {
          "instance": "line/main",
          "action": "SET_INTERCEPT"
        }
      ],
      "views": [
        {
          "ref": "views/AssemblyScene",
          "observations": [
            "observe-equation",
            "observe-yAtZero",
            "observe-yAtOne",
            "observe-rise",
            "observe-run"
          ]
        }
      ]
    }
  },
  "lesson": {
    "title": "Line slope",
    "instruction": "Change the slope and intercept. What happens to the line?",
    "explanation": "Change the slope and intercept. What happens to the line?"
  },
  "presentation": {
    "layout": "right",
    "view": "line",
    "particles": true,
    "directShading": true,
    "camera": "overview",
    "controls": [
      {
        "id": "control-slope",
        "capability": "slope",
        "label": "Slope",
        "target": "line/main",
        "widget": "slider",
        "slot": "primary",
        "min": -20,
        "max": 20,
        "step": 0.1
      },
      {
        "id": "control-intercept",
        "capability": "intercept",
        "label": "Intercept",
        "target": "line/main",
        "widget": "number",
        "slot": "primary",
        "min": -100,
        "max": 100,
        "step": 1
      },
      {
        "id": "control-reset",
        "capability": "reset",
        "label": "Reset",
        "target": "session",
        "widget": "button",
        "slot": "primary"
      }
    ],
    "results": [
      {
        "id": "result-equation",
        "output": "equation",
        "label": "Equation",
        "target": "line/main",
        "unit": "1",
        "precision": 2,
        "slot": "primary"
      },
      {
        "id": "result-yAtZero",
        "output": "yAtZero",
        "label": "y at x = 0",
        "target": "line/main",
        "unit": "math units",
        "precision": 2,
        "slot": "primary"
      },
      {
        "id": "result-yAtOne",
        "output": "yAtOne",
        "label": "y at x = 1",
        "target": "line/main",
        "unit": "math units",
        "precision": 2,
        "slot": "primary"
      },
      {
        "id": "result-rise",
        "output": "rise",
        "label": "Rise",
        "target": "line/main",
        "unit": "1",
        "precision": 2,
        "slot": "primary"
      },
      {
        "id": "result-run",
        "output": "run",
        "label": "Run",
        "target": "line/main",
        "unit": "1",
        "precision": 2,
        "slot": "primary"
      }
    ]
  },
  "editor": {
    "positions": {},
    "zoom": 0.7
  }
}

